import hashlib
import json
import os
import threading
import uuid
from pathlib import Path

STORE = Path("/var/lib/job-dispatch")
JOBS = STORE / "jobs"
ACCEPTED = Path("/var/lib/accepted-jobs")

_global_lock = threading.Lock()


def job_path(jid):
    """Storage filename is a hash of the opaque id; the id itself is preserved in the record."""
    h = hashlib.sha256(jid.encode("utf-8")).hexdigest()
    return JOBS / (h + ".json")


def _read(p):
    try:
        with open(p, "r", encoding="utf-8") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return None


def _write(p, data):
    tmp = p.with_name(p.name + ".tmp." + uuid.uuid4().hex)
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, p)


def ensure_dirs():
    JOBS.mkdir(parents=True, exist_ok=True)


def claim(jid):
    """Atomically claim an accepted job for exclusive processing.
    Renames <hash>.json to <hash>.claim if it does not already exist.
    Returns the claimed record dict, or None if unavailable/already claimed."""
    path = job_path(jid)
    claim = path.with_name(path.name + ".claiming")
    with _global_lock:
        try:
            os.rename(path, claim)
        except OSError:
            return None
    rec = _read(claim)
    if rec is None:
        try:
            claim.unlink()
        except OSError:
            pass
        return None
    return (claim, rec)


def store(rec):
    """Write a job record (must be called on a claimed path before finishing)."""
    p = job_path(rec["id"])
    _write(p, rec)


def get(jid):
    # If a claim file exists (crashed mid-claim), finish recovering it.
    path = job_path(jid)
    claim = path.with_name(path.name + ".claiming")
    if claim.exists() and not path.exists():
        rec = _read(claim)
        if rec is not None:
            _write(path, rec)
            try:
                claim.unlink()
            except OSError:
                pass
    return _read(path)


def all_jobs():
    """Return the set of opaque ids already ingested in the store."""
    return {rec["id"] for p in JOBS.glob("*.json") if (rec := _read(p))}

