if __name__ == "__main__":
    ingest_opaque()
    # Process opaque + any queued jobs, and keep claiming further work.
    process_job()
    while True:
        pending = False
        for p in JOBS.glob("*.json"):
            rec = _read(p)
            if rec and rec.get("status") != "completed":
                pending = True
                break
        if pending:
